        choices = c("rock" = 1, "pressure" = 2, "cars" = 3,
                    "Upload data" = 4)                     # NEW option
      ),
      # NEW: shown only when "Upload data" is selected
      conditionalPanel(
        condition = "input.dataset == '4'",
        fileInput("file", "Select a CSV file", accept = ".csv"),
        radioButtons("sep", "Column separator",
                     choices = c(";" = ";", "," = ","))
      ),
      actionButton("load", "Load dataset"),
      hr(),
      uiOutput("x_ui"),
      uiOutput("y_ui"),
      actionButton("analyze", "Update analysis")
    ),
    mainPanel(
      plotOutput("graph"),
      verbatimTextOutput("summary")
    )
  )
)

## file: server.R
library(shiny)

server &lt;- function(input, output, session) {

  # 1. LOAD THE DATASET
  dataInput &lt;- eventReactive(input$load, {
    if (input$dataset == 1) {
      rock
    } else if (input$dataset == 2) {
      pressure
    } else if (input$dataset == 3) {
      cars
    } else {
      req(input$file)                                   # NEW: wait for a file
      read.csv(input$file$datapath, sep = input$sep)    # NEW
    }
  })

  # 2. VARIABLE NAMES
  vars &lt;- reactive({
    names(dataInput())
  })

  # 3. DYNAMIC UI
  output$x_ui &lt;- renderUI({
    selectInput("x", "X variable:",
                choices = vars(),
                selected = vars()[1])
  })

  output$y_ui &lt;- renderUI({
    selectInput("y", "Y variable:",
                choices = vars(),
                selected = vars()[min(2, length(vars()))])
  })

  # 4. DATA FOR THE ANALYSIS
  newdata &lt;- eventReactive(input$analyze, {
    df &lt;- dataInput()
    df[, c(input$x, input$y), drop = FALSE]
  })

  # 5. OUTPUTS
  output$graph &lt;- renderPlot({
    df &lt;- newdata()
    x &lt;- df[[1]]
    y &lt;- df[[2]]
    if (is.factor(x) || is.character(x)) {
      boxplot(y ~ x, xlab = names(df)[1], ylab = names(df)[2])
    } else {
      plot(x, y, xlab = names(df)[1], ylab = names(df)[2], pch = 19)
    }
  })

  output$summary &lt;- renderPrint({
    summary(newdata())
  })
}

With example.csv, choose condition as X and tr as Y: you get a boxplot.
